fn count_uppercase(text: &Vec<char>) -> u64 {
    let mut count: u64 = 0;
    for &c in text.iter() {
        // ASCII 'A'..'Z' have code points 65 through 90
        if c >= 'A' && c <= 'Z' {
            count += 1;
        }
    }
    count
}

